    const previousLocale = persistedLocale.current;
    try {
      await appApiClient().request("/mini-app/locale", {
        method: "PATCH", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ locale: nextLocale }), signal: controller.signal,
      });
